            cpu_usage = 0.0
        records.append({"timestamp": timestamp, "cpu_usage": cpu_usage})
        time.sleep(interval)
    try:
        with open(LOGFILE_PATH, "w") as f:
            json.dump(records, f)
        return LOGFILE_PATH
    except IOError:
