            elapsed = time.time() - start_time
            if elapsed > 0:
                cpu_usage += (cpu_diff / elapsed) * 100
            memory_usage += max(0, new_mem - last_mem)
            last_cpu = new_cpu
            last_mem = new_mem
            if not p.is_running() or p.status() == psutil.STATUS_ZOMBIE:
                break
        except (psutil.NoSuchProcess, psutil.AccessDenied):
