import subprocess
import logging
def task_func(filepath):
    try:
        result = subprocess.run(['g++', filepath], capture_output=True, text=True, check=True)
        logging.info(f"Compilation of {filepath} was successful.")
    except subprocess.CalledProcessError as e:
        logging.error(f"Compilation of {filepath} failed. Error: {e.stderr}")
        raise
    except FileNotFoundError:
        logging.error("Compiler not found or file does not exist.")
        raise
